#!/usr/bin/env python3
"""Generate the Q16.16 sine lookup table used by src/core/fix_trig.h."""

from __future__ import annotations

import math
from pathlib import Path

SCALE = 65536
ENTRIES = 256


def main() -> None:
    root = Path(__file__).resolve().parents[1]
    output = root / "src" / "core" / "fix_trig_table.h"

    values = [
        int(round(math.sin(2.0 * math.pi * i / ENTRIES) * SCALE))
        for i in range(ENTRIES)
    ]

    lines = [
        "// Generated by scripts/gen_trig_table.py; do not edit by hand.",
        "#pragma once",
        "#include <cstdint>",
        "namespace nsync::core {",
        "inline constexpr std::int32_t kSinTable[256] = {",
    ]
    for i in range(0, ENTRIES, 8):
        lines.append("    " + ", ".join(str(value) for value in values[i : i + 8]) + ",")
    lines.extend(
        [
            "};",
            "} // namespace nsync::core",
            "",
        ]
    )

    output.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {output}")


if __name__ == "__main__":
    main()
